use strict;
use warnings;
use ExtUtils::MakeMaker;

WriteMakefile(
    NAME             => 'Log::Rotate::Daily',
    VERSION_FROM     => 'lib/Log/Rotate/Daily.pm',
    MIN_PERL_VERSION => '5.008001',
    PREREQ_PM        => { 'URI' => '1.60' },
    TEST_REQUIRES    => { 'Test::More' => '0.88' },
);

package Log::Rotate::Daily;
use strict;
use warnings;
use URI;

our $VERSION = '0.01';

sub keep {
    my ($class, @files) = @_;
    return @files > 7 ? @files[-7 .. -1] : @files;
}

1;

use strict;
use warnings;
use Test::More;
use Log::Rotate::Daily;

is(scalar(Log::Rotate::Daily->keep(1 .. 3)), 3, 'keeps all when few');
is(scalar(Log::Rotate::Daily->keep(1 .. 10)), 7, 'keeps seven files');

done_testing();
